/**
 * @event
 * @name scwin.grd_docPageList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_docPageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (typeof scwin.esgDisclosureCancel === 'function') { await scwin.esgDisclosureCancel(r["applNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.esgDisclosureCancel (열 취소)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.esgDisclosureCancel'); } return; } if (typeof scwin.esgDisclosurePreview === 'function') { await scwin.esgDisclosurePreview(r["applNo"], r["docNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.esgDisclosurePreview (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.esgDisclosurePreview'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_esgDisclosureCancel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_esgDisclosureCancel = async function () {
    const sbmOptions = {
        id: "tx_esgDisclosureCancel",
        method: "post",
        action: "/esg/searchESGDisclosureForm.do?method=esgEngDisclosureCancel",
        ref: "dma_esgDisclosureCancelReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil10607.tx_esgDisclosureCancel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

