/**
 * @method
 * @name scwin.esgEngSelectPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param applNo formCd formVer langTpCd disclsAcptTpCd mainFormNm disclsSubmitCorpIsurCd disclsTitle subcomDisclsYn
 * @returns
 * @hidden N
*/
scwin.esgEngSelectPop = async function (applNo, formCd, formVer, langTpCd, disclsAcptTpCd, mainFormNm, disclsSubmitCorpIsurCd, disclsTitle, subcomDisclsYn) {
    /* sdd-asis-lifecycle:begin esgEngSelectPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.checkRepFormVerYn(formCd, formVer)) {
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('applNo', applNo);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('mainFormNm', mainFormNm);
        $c.util.getComponent("slc_formCd").setValue(formCd);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('disclsAcptTpCd', disclsAcptTpCd);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('disclsSubmitCorpIsurCd', disclsSubmitCorpIsurCd);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('langTpCd', langTpCd);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('disclsTitle', disclsTitle);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('subcomDisclsYn', subcomDisclsYn);
        if (disclsAcptTpCd === 'F') {
            const url = '/jldfil00000/jldfil00000.xml';
            await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "_blank", width: "700", height: "740", scrollbars: true, resizable: true, type: "pageFramePopup" }, { method: "engDisclsProcessInspection", applNo: applNo, langTpCd: langTpCd, formCd: formCd, formVer: formVer, disclsAcptTpCd: disclsAcptTpCd });
        } else {
            if (disclsAcptTpCd === 'M' || disclsAcptTpCd === 'U' || disclsAcptTpCd === 'A') {
                (document.submitFrm || { elements: [] }).action = '/esg/writeESGSubmitInfoForm.do?method=writeEngSubmitInfo';
                await scwin.tx_esgEngSelectPop();
            }
        }
    } else {
        await $c.win.alert('해당 공시는 이전 서식버전이므로 제출할 수 없습니다. \'취소\' 후 최신 서식 버전으로 다시 보고서를 생성해 주세요.');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkRepFormVerYn
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formVer
 * @returns
 * @hidden N
*/
scwin.checkRepFormVerYn = function (formCd, formVer) {
    /* sdd-asis-lifecycle:begin checkRepFormVerYn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const xhr = new XMLHttpRequest();
    const url = '/esg/searchESGDisclosureForm.do?method=checkRepFormVerYn&' + 'formCd=' + formCd + '&formVer=' + formVer;
    xhr.open('GET', url, false);
    xhr.setRequestHeader('Cache-Control', 'no-cache');
    xhr.setRequestHeader('Pragma', 'no-cache');
    xhr.setRequestHeader('If-Modified-Since', '0');
    xhr.send();
    if (xhr.status == 200) {
        const result = (typeof xhr.response === "string" ? (typeof xhr.response === "string" ? JSON.parse(xhr.response) : xhr.response) : xhr.response);
        if (result.repFormVerYn === 'Y') {
            return true;
        } else {
            return false;
        }
    }
    /* sdd-asis-lifecycle:end */
};


